func TestAccComputeHaController_failoverThenDelete_noDiff(t *testing.T) {
	t.Parallel()
	os.Setenv("TF_COMPUTE_INSTANCE_DISABLE_MULTIPLE_ZONE_CHECK", "1")

	zone1 := "us-central1-a"
	zone2 := "us-central1-b"
	region := "us-central1"
	nic0 := "nic0"
	nic1 := "nic1"

	hacName := fmt.Sprintf("tf-test-%s", acctest.RandString(t, 10))
	context := map[string]any{
		"hac_name":       hacName,
		"zone1":          zone1,
		"zone2":          zone2,
		"region":         region,
		"nic0":           nic0,
		"nic1":           nic1,
		"network_0_name": tpgcompute.BootstrapSharedTestNetwork(t, "hac-failover-sip-net0"),
		"network_1_name": tpgcompute.BootstrapSharedTestNetwork(t, "hac-failover-sip-net1"),
	}

	acctest.VcrTest(t, resource.TestCase{
		PreCheck:                 func() { acctest.AccTestPreCheck(t) },
		ProtoV5ProviderFactories: acctest.ProtoV5ProviderFactories(t),
		Steps: []resource.TestStep{
			{
				Config: testAccHaControllerBasic(context),
			},
			{
				PreConfig: func() {
					config := acctest.GoogleProviderConfig(t)

					url, err := tpgcompute.HaControllerPreviewURL(fmt.Sprintf("%sprojects/%s/regions/%s/haControllers/%s",
						transport_tpg.BaseUrl(tpgcompute.Product, config), config.Project, region, hacName))
					if err != nil {
						t.Fatalf("Failed to build HaController URL: %v", err)
					}

					res, err := transport_tpg.SendRequest(transport_tpg.SendRequestOptions{
						Config:    config,
						Method:    "GET",
						Project:   config.Project,
						RawURL:    url,
						UserAgent: config.UserAgent,
					})
					if err != nil {
						t.Fatalf("Failed to GET HaController %s: %v", hacName, err)
					}

					var primaryZone string
					if status, ok := res["status"].(map[string]any); ok {
						if pZone, ok := status["primaryZone"].(string); ok {
							primaryZone = pZone
						}
					}

					var targetZone string
					if primaryZone == zone1 {
						targetZone = zone2
					} else {
						targetZone = zone1
					}

					req := map[string]any{
						"failoverToZone": targetZone,
					}

					failoverURL, err := tpgcompute.HaControllerPreviewURL(fmt.Sprintf("%sprojects/%s/regions/%s/haControllers/%s/failover",
						transport_tpg.BaseUrl(tpgcompute.Product, config), config.Project, region, hacName))
					if err != nil {
						t.Fatalf("Failed to build HaController failover URL: %v", err)
					}

					op, err := transport_tpg.SendRequest(transport_tpg.SendRequestOptions{
						Config:    config,
						Method:    "POST",
						Project:   config.Project,
						RawURL:    failoverURL,
						UserAgent: config.UserAgent,
						Body:      req,
					})
					if err != nil {
						t.Fatalf("Failed to trigger failover for HaController %s: %v", hacName, err)
					}

					if waitErr := tpgcompute.ComputeOperationWaitTime(config, op, config.Project, "waiting failover to finish", config.UserAgent, 10*time.Minute); waitErr != nil {
						t.Fatalf("Error waiting for failover: %s", waitErr)
					}
				},
				Config: testAccHaControllerNoHac(context),
				ConfigPlanChecks: resource.ConfigPlanChecks{
					PreApply: []plancheck.PlanCheck{
						plancheck.ExpectResourceAction("google_compute_instance.vm", plancheck.ResourceActionNoop),
					},
				},
			},
			{
				Config:             testAccHaControllerNoHac(context),
				ExpectNonEmptyPlan: false,
			},
		},
	})
}

func testAccHaControllerBasic(context map[string]any) string {
	return testAccHaControllerNoHac(context) + acctest.Nprintf(`
resource "google_compute_ha_controller" "foobar" {
  name                = "%{hac_name}"
  region              = "%{region}"
  instance_name       = google_compute_instance.vm.name
  failover_initiation = "MANUAL_ONLY"

  zone_configuration {
    zone = "%{zone1}"
    instance_network_interface {
      name       = "%{nic0}"
      network_ip = google_compute_address.ipv4_nic0_zone1.address
    }
    instance_network_interface {
      name       = "%{nic1}"
      network_ip = google_compute_address.ipv4_nic1_zone1.address
    }
  }
  zone_configuration {
    zone = "%{zone2}"
    instance_network_interface {
      name       = "%{nic0}"
      network_ip = google_compute_address.ipv4_nic0_zone2.address
    }
    instance_network_interface {
      name       = "%{nic1}"
      network_ip = google_compute_address.ipv4_nic1_zone2.address
    }
  }
}
`, context)
}

